package com.example.crm.sales; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/deals") public class DealController {final DealService s; DealController(DealService x){s=x;} record Req(@NotBlank String title,BigDecimal amount,UUID customerId){} @GetMapping public ResponseEntity<List<DealDto>> all(){return ResponseEntity.ok(s.all());} @GetMapping("/{id}") public ResponseEntity<DealDto> one(@PathVariable UUID id){try{return ResponseEntity.ok(s.one(id));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @PostMapping @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<DealDto> create(@Valid @RequestBody Req r){return ResponseEntity.status(201).body(s.create(r.title(),r.amount(),r.customerId()));} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<DealDto> update(@PathVariable UUID id,@Valid @RequestBody Req r){try{return ResponseEntity.ok(s.update(id,r.title(),r.amount(),r.customerId()));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @PatchMapping("/{id}/stage") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<DealDto> stage(@PathVariable UUID id,@RequestParam Deal.Stage value){try{return ResponseEntity.ok(s.stage(id,value));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable UUID id){try{s.delete(id);return ResponseEntity.noContent().build();}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} }
